// Part: room: west hall bath (plan.md ROOMS/FLOORS; box [40,11,54,43,16,60], door from the west corridor at z53 x41..42).
// Hall bath for bedrooms 2-4: a tub on the south wall (focal, faces the door), a basin washstand on the east wall,
// candles and a lantern for light. The lane x41..42 stays clear from the door to the tub.
import { layers } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const ORIGIN = [40, 11, 54]; // grid cell of the room's top-left (x40, z54); rows run along +x, then +z

export function build(g) {
  // Floor furniture, row y11 (on the floor block at y10). '.' is left as is.
  layers(g, ORIGIN, {
    C: ["chest", { facing: "east" }], // linen chest
    b: "barrel", // dresser barrels (west wall) and basin stand (east wall)
    S: ["dark_oak_stairs", { facing: "west", half: "bottom" }], // chair by the basin
    F: "dark_oak_fence", // towel post
    R: "white_carpet", // bath mat in the lane
    K: "cauldron", // tub ends
    W: ["water_cauldron", { level: "3" }], // the tub, centred on the door
  }, [
    ["C..b", "b..b", "...S", "b...", ".RRF", ".RR.", "KWWK"],
  ]);

  // Things standing on the barrels and the fence: row y12.
  layers(g, [40, 12, 54], {
    p: "flower_pot", // pot on the west dresser
    K: "cauldron", // basin on the east stand
    c: ["candle", { candles: "4", lit: "true" }], // lit candles on the west barrel
    w: "white_wool", // towel on the fence post
  }, [
    ["....", "p..K", "....", "c...", "...w", "....", "...."],
  ]);

  // Light: three hanging lanterns on chains from the ceiling (plate y17), spaced so every floor cell is 8+.
  layers(g, [40, 15, 54], {
    L: ["lantern", { hanging: "true" }],
  }, [
    ["....", "..L.", "....", ".L..", "....", "...L", "...."],
  ]);
  layers(g, [40, 16, 54], {
    I: ["iron_chain", { axis: "y" }],
  }, [
    ["....", "..I.", "....", ".I..", "....", "...I", "...."],
  ]);
}
